
  create table "public"."Socios" (
    "id" bigint generated by default as identity not null,
    "email" character varying,
    "name" character varying,
    "user_id" uuid
      );


alter table "public"."Socios" enable row level security;


  create table "public"."Temporadas" (
    "id" bigint generated by default as identity not null,
    "name" character varying not null
      );


alter table "public"."Temporadas" enable row level security;


  create table "public"."Torneos" (
    "id" bigint generated by default as identity not null,
    "name" character varying,
    "description" text,
    "start_date" timestamp without time zone
      );


alter table "public"."Torneos" enable row level security;

CREATE UNIQUE INDEX "Socios_email_key" ON public."Socios" USING btree (email);

CREATE UNIQUE INDEX "Socios_pkey" ON public."Socios" USING btree (id);

CREATE UNIQUE INDEX "Socios_user_id_key" ON public."Socios" USING btree (user_id);

CREATE UNIQUE INDEX "Temporadas_pkey" ON public."Temporadas" USING btree (id);

CREATE UNIQUE INDEX "Torneos_pkey" ON public."Torneos" USING btree (id);

alter table "public"."Socios" add constraint "Socios_pkey" PRIMARY KEY using index "Socios_pkey";

alter table "public"."Temporadas" add constraint "Temporadas_pkey" PRIMARY KEY using index "Temporadas_pkey";

alter table "public"."Torneos" add constraint "Torneos_pkey" PRIMARY KEY using index "Torneos_pkey";

alter table "public"."Socios" add constraint "Socios_email_key" UNIQUE using index "Socios_email_key";

alter table "public"."Socios" add constraint "Socios_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."Socios" validate constraint "Socios_user_id_fkey";

alter table "public"."Socios" add constraint "Socios_user_id_key" UNIQUE using index "Socios_user_id_key";

