  create policy "Only self can query their data"
  on "public"."Socios"
  as permissive
  for select
  to public
using ((user_id = auth.uid()));



  create policy "Anyone can read"
  on "public"."Temporadas"
  as permissive
  for select
  to public
using (true);



  create policy "Only admin can write"
  on "public"."Temporadas"
  as permissive
  for all
  to public
using ((auth.role() = 'admin'::text));



  create policy "Everyone can read"
  on "public"."Torneos"
  as permissive
  for select
  to public
